-- GameXS editorial overviews, part 10 (ps5_games.overview, migration 040).
--
-- Same format and rules as db/content/game_overviews.sql: original Persian copy
-- written for GameXS; no text was copied. Facts checked against the IGDB data
-- stored in ps5_games. Slugs whose IGDB row describes a different product than
-- the shops sell are skipped and listed in db/content/catalog_mismatches_part10.md.
--
-- Shape: {"intro", "suits": [..], "sections": [{"heading", "paragraphs": [..], "media"}]}
-- media = "trailer" | "screenshot:N" (1-based index into screenshot_ids); a key
-- the game has no asset for is skipped at render time.
--
-- Idempotent: re-running overwrites the overview of each listed slug and
-- touches nothing else. Apply with:
--   docker exec -i gamexs-postgres psql -U gamexs -d gamexs -v ON_ERROR_STOP=1 < db/content/game_overviews_part10.sql

UPDATE ps5_games g
SET overview = v.overview::jsonb
FROM (VALUES
('ea-sports-fc-27', $j${
  "intro": "EA Sports FC 27 تازه‌ترین شماره از سری فوتبالی EA Sports است که استودیو EA Vancouver آن را ساخته و در سپتامبر ۲۰۲۶ منتشر شده است. این سری از زمان جدایی EA از نام فیفا با عنوان EA Sports FC ادامه پیدا کرده و هر سال با تیم‌ها، بازیکنان و ترکیب‌های به‌روز شده عرضه می‌شود. شعار این نسخه «بازی جهان» است و سازندگان روی گیم‌پلی نزدیک‌تر به فوتبال واقعی و کنترل بیشتر بازیکن در همه حالت‌ها تأکید کرده‌اند.",
  "suits": [
    "طرفداران فوتبال",
    "بازیکنان آنلاین و رقابتی",
    "بازی دونفره روی یک کنسول"
  ],
  "sections": [
    {
      "heading": "چه چیزهایی در FC 27 تازه است؟",
      "paragraphs": [
        "مهم‌ترین تازگی این نسخه بخشی به نام The Grounds است؛ زمین بازی‌ای که فوتبال خیابانی را با حال‌وهوای استادیوم ترکیب می‌کند و فضایی آزادتر و سرگرم‌کننده‌تر از مسابقه رسمی یازده‌نفره دارد. در کنار آن، EA می‌گوید بسیاری از تغییرات گیم‌پلی این سال بر اساس بازخورد جامعه بازیکنان انجام شده تا حرکت بازیکنان، پاس‌ها و دفاع حس طبیعی‌تری داشته باشند.",
        "مثل هر نسخه سالانه، فهرست باشگاه‌ها، لیگ‌ها و ترکیب تیم‌ها به‌روز شده است، پس اگر می‌خواهید با نقل‌وانتقالات فصل جدید بازی کنید، این نسخه گزینه طبیعی است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "حالت‌های بازی",
      "paragraphs": [
        "سری FC همیشه مجموعه‌ای از حالت‌ها را کنار هم دارد: از مسابقه سریع با دوستان روی یک کنسول و حالت کریر مربی و بازیکن برای کسانی که دوست دارند یک تیم یا یک ستاره را فصل‌به‌فصل جلو ببرند، تا Ultimate Team که در آن تیم رؤیایی‌تان را با کارت بازیکنان می‌سازید و با بقیه بازیکنان آنلاین رقابت می‌کنید.",
        "بخش بزرگی از جذابیت بلندمدت بازی در حالت‌های آنلاین است؛ رویدادهای فصلی، مسابقات رتبه‌بندی و چالش‌های هفتگی باعث می‌شوند بازی تا انتشار نسخه بعدی هم تازه بماند."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "تجربه روی PS5",
      "paragraphs": [
        "روی PS5 بازی از بارگذاری سریع و لرزش و ماشه‌های تطبیقی دسته DualSense بهره می‌برد و جزئیات استادیوم، نور و انیمیشن بازیکنان را بهتر از نسخه‌های نسل قبل نشان می‌دهد. اگر عادت دارید با دوستتان کنار هم بازی کنید، حالت دونفره آفلاین هم همچنان در دسترس است."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "اگر فقط مسابقه آفلاین و حالت کریر را می‌خواهید، اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اما بیشتر بازیکنان FC برای Ultimate Team و مسابقات آنلاین سراغ آن می‌روند؛ در این صورت ظرفیت ۱ مناسب نیست و باید ظرفیت ۲ یا ۳ را انتخاب کنید. ظرفیت ۲ هم آنلاین و هم آفلاین کار می‌کند و ظرفیت ۳ ارزان‌تر اما فقط آنلاین است. برای حالت‌های آنلاین روی PS5 معمولاً اشتراک PS Plus هم لازم است. قیمت همه روش‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('hello-neighbor-2', $j${
  "intro": "Hello Neighbor 2 دنباله بازی معروف مخفی‌کاری و وحشت Hello Neighbor است که استودیو Eerie Guest Studios ساخته و tinyBuild در دسامبر ۲۰۲۲ منتشر کرده است. این بار به‌جای یک خانه، کل شهرک کوچک ریون بروکس پیش روی شماست و باید راز ناپدید شدن آقای پیترسون، همسایه مرموز نسخه اول، را کشف کنید. بازی ترکیبی از معما، دزدکی وارد خانه‌ها شدن و فرار از دشمنی است که رفتار شما را یاد می‌گیرد.",
  "suits": [
    "طرفداران وحشت سبک و خانوادگی",
    "علاقه‌مندان معما و مخفی‌کاری",
    "نوجوانان و بازیکنان کنجکاو"
  ],
  "sections": [
    {
      "heading": "داستان و فضا",
      "paragraphs": [
        "ریون بروکس شهرکی معمولی است که بیش از حد کلاغ دارد و اتفاق‌های عجیبی در آن می‌افتد؛ حال‌وهوایی که کمی یادآور کارتون‌های تیم برتون است. شما در نقش یک کارآگاه خصوصی که به‌دنبال آقای پیترسون می‌گردد، وارد خانه‌ها و مغازه‌های شهر می‌شوید، سرنخ جمع می‌کنید و کم‌کم می‌فهمید پشت این ماجرا چیزی بزرگ‌تر از یک همسایه بدخلق است.",
        "فضای بازی با رنگ‌های اغراق‌شده و طراحی کارتونی بیشتر ترسناک‌بامزه است تا خشن، به همین دلیل برای مخاطب جوان‌تر هم مناسب است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی: دشمنی که یاد می‌گیرد",
      "paragraphs": [
        "مهم‌ترین ویژگی سری Hello Neighbor هوش مصنوعی آن است. موجود مرموزی که شما را تعقیب می‌کند مسیرهای تکراری‌تان را به خاطر می‌سپارد و رفتارش را با شما تطبیق می‌دهد؛ اگر همیشه از یک پنجره وارد شوید، دیر یا زود همان‌جا منتظرتان می‌ماند. پس باید راه‌های تازه پیدا کنید، حواس دشمن را پرت کنید و زمان‌بندی را درست انتخاب کنید.",
        "معماهای بازی بر پایه جابه‌جا کردن اشیا، پیدا کردن کلید و ترکیب ابزارهاست و کشف راه‌حل‌ها گاهی به آزمون‌وخطا نیاز دارد."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر از بازی‌هایی لذت می‌برید که در آن باید آرام و با دقت جلو بروید و از کشف رمزوراز یک مکان خوشتان می‌آید، Hello Neighbor 2 تجربه سرگرم‌کننده‌ای است. بازیکنانی که به دنبال اکشن یا وحشت جدی هستند احتمالاً آن را بیش از حد سبک می‌دانند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Hello Neighbor 2 بازی تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر کنسولتان همیشه به اینترنت وصل است، ظرفیت ۲ انعطاف بیشتری دارد و محدودیت آفلاین ماندن ندارد. اگر نسخه فیزیکی را ترجیح می‌دهید، ظرفیت‌ها برایش معنایی ندارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('the-witcher-3-wild-hunt-complete-edition', $j${
  "intro": "The Witcher 3: Wild Hunt – Complete Edition نسخه کامل یکی از تحسین‌شده‌ترین نقش‌آفرینی‌های جهان‌باز تاریخ است که CD Projekt RED ساخته است. این بسته بازی اصلی، دو گسترش بزرگ Hearts of Stone و Blood and Wine و همه محتوای رایگان را در خود دارد. نسخه نسل جدید آن در سال ۲۰۲۲ برای PS5 منتشر شد و با گرافیک بهبودیافته، بارگذاری سریع و پشتیبانی از DualSense بهترین راه تجربه این شاهکار روی کنسول است.",
  "suits": [
    "عاشقان نقش‌آفرینی و داستان",
    "علاقه‌مندان جهان‌باز",
    "بازیکنانی که بازی طولانی می‌خواهند"
  ],
  "sections": [
    {
      "heading": "داستان گرالت",
      "paragraphs": [
        "شما در نقش گرالت اهل ریویا، شکارچی هیولاهای حرفه‌ای که به او ویچر می‌گویند، بازی می‌کنید. داستان در دوره‌ای تاریک جریان دارد؛ امپراتوری نیلفگارد به قلمروهای شمالی حمله کرده و ارتش اشباح موسوم به شکار وحشی در پی سیری، دختری است که گرالت او را مثل فرزند خود بزرگ کرده. جست‌وجوی سیری محور اصلی ماجراست، اما در مسیر با ده‌ها داستان فرعی روبه‌رو می‌شوید که بسیاری از آن‌ها به اندازه داستان اصلی به‌یادماندنی‌اند.",
        "تصمیم‌های شما در گفت‌وگوها و مأموریت‌ها گاهی پیامدهای دیرهنگام و غیرمنتظره دارند و پایان‌های مختلفی را رقم می‌زنند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "دو گسترش بزرگ",
      "paragraphs": [
        "Hearts of Stone داستانی تاریک‌تر درباره قراردادی خطرناک با مردی مرموز به نام گاونتر اُدیم روایت می‌کند. Blood and Wine تقریباً یک بازی کامل است؛ گرالت را به سرزمین آفتابی و شاعرانه توسنت می‌برد و با منطقه‌ای بزرگ، تجهیزات و ماجراهای تازه، حکم پایانی شایسته برای داستان او را دارد."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "گیم‌پلی و جهان بازی",
      "paragraphs": [
        "مبارزه ترکیبی از شمشیرزنی، جادوهای ویچری موسوم به نشانه‌ها، معجون و روغن مخصوص هیولاهاست و آماده‌شدن پیش از هر شکار بخشی از لذت بازی است. جهان بازی از شهر بزرگ نوویگراد تا جزایر اسکلیگه پر از روستا، خرابه، گنج و قراردادهای شکار است. بازی ورق گوئنت هم آن‌قدر محبوب شد که بعدها بازی مستقل خود را پیدا کرد.",
        "تجربه کامل این بسته به‌راحتی بیش از صد ساعت طول می‌کشد."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "The Witcher 3 کاملاً تک‌نفره است، بنابراین اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر کنسولتان همیشه آنلاین است، ظرفیت ۲ انعطاف بیشتری دارد. در نسخه دیسک، ظرفیت‌ها معنا ندارد و دیسک را می‌توانید بعداً بفروشید. قیمت روش‌های مختلف را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('a-quiet-place-the-road-ahead', $j${
  "intro": "A Quiet Place: The Road Ahead یک بازی ماجرایی ترسناک تک‌نفره است که از مجموعه فیلم‌های موفق «یک مکان ساکت» الهام گرفته شده. استودیو ایتالیایی Stormind Games آن را ساخته و Saber Interactive در اکتبر ۲۰۲۴ منتشر کرده است. قانون بازی همان قانون فیلم‌هاست: هر صدایی ممکن است آخرین صدای شما باشد.",
  "suits": [
    "طرفداران فیلم‌های A Quiet Place",
    "علاقه‌مندان وحشت آرام و پرتنش",
    "بازیکنان داستان‌محور"
  ],
  "sections": [
    {
      "heading": "داستان",
      "paragraphs": [
        "بازی داستانی مستقل در دنیای فیلم‌ها روایت می‌کند. شخصیت اصلی زن جوانی به نام الکس است که پس از هجوم موجودات مرگبار باید در دنیایی ویران زنده بماند. در کنار خطر بیرونی، او با کشمکش‌های خانوادگی و ترس‌های درونی خودش هم دست‌وپنجه نرم می‌کند و همین بعد شخصی، داستان را از یک فرار ساده فراتر می‌برد.",
        "شخصیت اصلی به آسم مبتلاست و نفس‌تنگی او بخشی از چالش زنده ماندن است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی: سکوت یعنی زندگی",
      "paragraphs": [
        "در این بازی خبری از سلاح و درگیری نیست؛ شما باید با دقت قدم بردارید، مراقب سطح زیر پایتان باشید و از اشیایی که سروصدا می‌کنند دوری کنید. موجودات کور هستند اما شنوایی فوق‌العاده‌ای دارند، پس یک شیشه شکسته یا دری که بد بسته شود کافی است تا لو بروید. ابزاری برای سنجیدن میزان صدای محیط به شما کمک می‌کند بفهمید چه زمانی می‌توانید کمی سریع‌تر حرکت کنید.",
        "در صورت پشتیبانی تنظیمات، صدای میکروفون خود بازیکن هم می‌تواند در تشخیص سروصدا نقش داشته باشد که تنش بازی را بیشتر می‌کند."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر وحشت آهسته و پرتنش را به ترس‌های ناگهانی و اکشن ترجیح می‌دهید، این بازی تجربه‌ای فشرده و به‌یادماندنی است. ریتم کند و تمرکز بر مخفی‌کاری ممکن است به مذاق کسانی که به‌دنبال هیجان سریع‌اند خوش نیاید."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "این بازی کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر نمی‌خواهید کنسول را آفلاین نگه دارید، ظرفیت ۲ انعطاف بیشتری دارد. نسخه فیزیکی هم برای کسانی که دیسک را ترجیح می‌دهند در دسترس است و ظرفیت‌ها برای آن معنایی ندارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),
('call-of-duty-modern-warfare', $j${
  "intro": "Call of Duty: Modern Warfare نسخه سال ۲۰۱۹ سری مشهور کال آو دیوتی است که Infinity Ward آن را به‌عنوان بازآغاز زیرمجموعه Modern Warfare ساخت. بازی با کمپین تک‌نفره‌ای واقع‌گرایانه و پرتنش، ماموریت‌های همکاری Special Ops و بخش چندنفره گسترده با پشتیبانی از بازی میان‌پلتفرمی عرضه شد و یکی از پرطرفدارترین شوترهای نسل خود بود. نسخه PS4 بازی روی PS5 هم اجرا می‌شود.",
  "suits": [
    "طرفداران شوتر اول‌شخص",
    "بازیکنان چندنفره رقابتی",
    "علاقه‌مندان داستان‌های نظامی"
  ],
  "sections": [
    {
      "heading": "کمپین داستانی",
      "paragraphs": [
        "داستان با گم شدن محموله‌ای از سلاح‌های شیمیایی در یک عملیات مخفی در اروپای شرقی آغاز می‌شود و یک روز بعد، بمب‌گذاران انتحاری یک گروه تروریستی به لندن حمله می‌کنند. شما میان چند شخصیت جابه‌جا می‌شوید، از جمله کاپیتان پرایس و یک افسر سیا، و درگیر عملیاتی می‌شوید که مرز میان درست و نادرست در آن چندان روشن نیست.",
        "کمپین بر واقع‌گرایی تاکتیکی تأکید دارد؛ تشخیص غیرنظامی از دشمن در لحظه، عملیات شبانه با دید در شب و فضاهای بسته و پرتنش از ویژگی‌های آن است."
      ],
      "media": "screenshot:1"
    },
    {
