('devil-may-cry-hd-collection', $j${
  "intro": "Devil May Cry HD Collection مجموعه‌ای از نسخه‌های بازسازی‌شده با کیفیت HD سه بازی اول سری Devil May Cry است که Capcom ابتدا در سال ۲۰۱۲ منتشر کرد و نسخه به‌روزتر آن در سال ۲۰۱۸ برای PS4 عرضه شد. این سه بازی که در اصل برای PS2 ساخته شده بودند، پایه‌گذار سبک اکشن هک‌اند‌اسلش سبک‌دار بودند. نسخه PS4 مجموعه روی PS5 هم اجرا می‌شود.",
